<?php require 'db.php';require 'helpers.php';page_header('Practical 13 - Fetch API');?><section class="panel"><h2>Events JSON API + Fetch</h2><p>Events below are loaded from <code>api/events.php</code> without a full page reload. Admin users can create/delete events.</p><div id="status"></div><div id="events"></div><?php if(!empty($_SESSION['user'])&&$_SESSION['user']['role']==='admin'):?><h3>Add Event</h3><form id="eventForm"><label>Event name</label><input name="event_name" required><label>Date</label><input name="event_date" type="date" required><label>Venue</label><input name="venue" required><button>Add using Fetch</button></form><?php endif;?></section><script>const statusBox=document.getElementById('status'),root=document.getElementById('events');async function load(){try{let r=await fetch('api/events.php');let j=await r.json();if(!j.ok)throw Error(j.error);root.innerHTML=j.data.map(e=>`<p><b>${escapeHtml(e.event_name)}</b> — ${escapeHtml(e.event_date)} · ${escapeHtml(e.venue)} ${e.status==='open'?'':'(closed)'} <?php if(!empty($_SESSION['user'])&&$_SESSION['user']['role']==='admin'):?><button data-delete="${e.id}">Delete</button><?php endif;?></p>`).join('')||'No events found';}catch(e){statusBox.textContent=e.message}}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}root.addEventListener('click',async e=>{if(e.target.dataset.delete){let r=await fetch('api/events.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'delete',id:e.target.dataset.delete})});let j=await r.json();statusBox.textContent=j.ok?'Event deleted':j.error;load();}});document.getElementById('eventForm')?.addEventListener('submit',async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.action='create';let r=await fetch('api/events.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let j=await r.json();statusBox.textContent=j.ok?'Event created':j.error;if(j.ok)e.target.reset();load();});load();</script><?php page_footer();?>